


-- tập KH có lịch sử đơn gần nhất thuộc các siêu thị ở HCM nhé



-- store list: thay (101,102,103) theo nhu cầu
WITH act_2024 AS (
    SELECT DISTINCT a.crmcustomerid AS customer_id
    FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
    JOIN "pinot-group01"."default".bhx_inventory_inv_outputvoucherdetail b
        ON a.outputvoucherid = b.outputvoucherid
    WHERE from_unixtime(a.outputdate / 1000 - 25200) >= DATE '2024-01-01'
      AND b.outputtypeid IN (1903, 3)
      AND a.crmcustomerid > 5
),
last_overall AS (
    SELECT
        a.crmcustomerid AS customer_id,
        MAX(from_unixtime(a.outputdate / 1000 - 25200)) AS last_time,
        max_by(a.storeid, from_unixtime(a.outputdate / 1000 - 25200)) AS last_storeid
    FROM "pinot-group01"."default".bhx_inventory_inv_outputvoucher a
    WHERE a.crmcustomerid > 5
    AND from_unixtime(a.outputdate / 1000 - 25200) >= DATE '2025-01-01'
    GROUP BY a.crmcustomerid
)
SELECT l.customer_id, l.last_storeid, l.last_time
FROM last_overall l
JOIN act_2024 s on l.customer_id = s.customer_id
